mapper.select:
select sd.D_Name as icmDName, pro.P_Name as pName, con.Con_Name as conName, pro.P_Name_History as pNameHistory, proc.C_Name as pConstructionUnitName, proc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, ipv.Ipv_Budget_Total as ipvBudgetTotal, ipv.Ipv_Planned_Investment as ipvPlannedInvestment, ipv.Ipv_Carry_Over as ipvCarryOver, ipv.Ipv_Scheduled_Plan as ipvScheduledPlan, ipv.Ipv_Accumulated_Schedule as ipvAccumulatedSchedule, ipv.Ipv_Declare_Year as ipvDeclareYear, ( select sum(icm.Icm_Budget_Investment) from Inv_Complete_Month icm where icm.Icm_Reporting_Year < mn.Icm_Reporting_Year and icm.Icm_Reporting_Month='12' ) as icmAllBudgetInv, mn.* from Inv_Complete_Month mn left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID left join Inv_Plan_Year ipv on ipv.Ipv_Id=mn.Ipv_Id where 1=1
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Icm_D_Id=#{params.icmDId}
order by mn.Icm_Reporting_Year,mn.Icm_Reporting_Month asc

        select
        
        pro.P_Record_Amount as pRecordAmount,
        pro.p_project_form_type as pProjectFormType,
        pro.p_approval_amount as pApprovalAmount,
        sdp.d_name as pDepartmentName,
        con.Con_Name as conName,
        ipv.Ipv_P_Type,
        ipv.ipv_Construction_Stage as ipvConstructionStage,
        ipv.ipv_construction_status as ipvConstructionStatus,
        ipv.report_table_num + 0 as reportTableNum,
        ipv.Ipv_Planned_Investment as ipvPlannedInvestment,
        ipv.Ipv_Start as ipvStart,
        ipv.Ipv_End as ipvEnd,
        ims.Ims_Planned_Inv,
        ims.ims_cumulative_inv,
        ims.ims_cumulative_inv_proportion,
        
            NVL(jbrAgg.all_names, u.u_name) as cjJbr,
        
        depAgg.dep_names as pCompetentDepartmentNames,
        mn.*
        from Inv_Complete_Month mn
        left join Con_Contract con on con.Con_Id = mn.Con_Id
        Left join Inv_Plan_Year ipv ON mn.p_id = ipv.p_id and mn.icm_reporting_year = ipv.Ipv_Declare_Year and Ipv_State != 1 and ipv_state != 3
        LEFT join Inv_Monthly_Schedule ims ON ims.Ipv_Id = ipv.Ipv_Id and ims.Ims_Month = mn.Icm_Reporting_Month
        
        
            
        
        
            
        
        
        left join SYS_Department sdp on pro.p_Department=sdp.D_ID
        left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID
        
            ${params.authSql}
        
        
            WHERE 1=1
        

        
            and mn.Te_Id = #{params.teId}
        
        
            and mn.Icm_Create_Uid = #{params.createdBy}
        
        
            and mn.Icm_D_Id = #{params.icmDId}
        
        
            and mn.P_Id = #{params.pId}
        
        
            and mn.Icm_Reporting_Year = #{params.icmReportingYear}
        
        
            and mn.Icm_Reporting_Month = #{params.icmReportingMonth}
        
        
            and mn.Icm_State = #{params.icmState}
        
        
            
                
                    and likePname(#{params.pName},pro.P_Id)=true
                
                
                    and pro.P_Name like concat('%',#{params.pName},'%')
                
            
        
        
            and pro.P_Competent_Department = #{params.pCompetentDepartment}
        
        
            and mn.transfer_status in
            
                #{item}
            
        
        
            and ipv.Ipv_P_Type in
            
                #{item}
            
        
        
            and mn.plan_complete_result IN
            
                #{item}
            
        
        
            and mn.complete_result IN
            
                #{item}
            
        
        
            and mn.month_cumulative_inv_proportion < #{params.monthCumulativeInvProportion}
        
        
            and ipv.ipv_p_type in
            
                #{type}
            
        
        
            and ipv.Ipv_Construction_stage in
            
                #{stage}
            
        
        
            and
            
                INSTR(ipv.Ipv_Construction_stage, #{ipvStaqe})
            
        
        
            and pro.p_name  in
            
                #{pName}
            
        
        
            and (sdp.D_Name in
            
                #{pDepartmentName}
            
            
                or (sdp.D_Name is null or sdp.D_Name = '')
            
            )
        
        
            and (depAgg.dep_names in
            
                #{pCompetentDepartmentName}
            
            
                or (depAgg.dep_names is null or depAgg.dep_names = '')
            
            )
        
        
            and (mn.icm_Create_Uname  in
            
                #{createUname}
            
            
                or (mn.icm_Create_Uname is null or mn.icm_Create_Uname = '')
            
            )
        
        
            and ( pro.p_Competent_Department in
            
                #{dep}
            
            or
            pro.P_Department in
            
                #{dep}
            
            )
        
        
            and ((
            jbrHit.p_id is not null
            or exists (
            select 1
            from sys_user engineer
            where engineer.u_id = pro.P_Engineer
            and engineer.u_name in
            
                #{jbr}
            
            ))
            
                or (
                jbrAgg.p_id is null
                and pro.P_Engineer is null
                )
            
            )
        
        
            and (ipv.ipv_construction_status in
            
                #{status}
            
            
                or (ipv.ipv_construction_status is null or ipv.ipv_construction_status = '')
            
            )
        
        
            
        
        
            
                order by mn.${params.sortFiled} ${params.sortType}
            
            
                
                    order by TO_NUMBER(ipv.report_table_num) ${params.sortType}
                
                
                    order by ${params.sortSideFiled} ${params.sortType}
                
            
            
                order by mn.Icm_Create_Time desc

        select
        
        pro.P_Record_Amount as pRecordAmount,
        pro.p_project_form_type as pProjectFormType,
        pro.p_approval_amount as pApprovalAmount,
        sdp.d_name as pDepartmentName,
        con.Con_Name as conName,
        ipv.Ipv_P_Type,
        ipv.ipv_Construction_Stage as ipvConstructionStage,
        ipv.ipv_construction_status as ipvConstructionStatus,
        ipv.report_table_num + 0 as reportTableNum,
        ipv.Ipv_Planned_Investment as ipvPlannedInvestment,
        ipv.Ipv_Start as ipvStart,
        ipv.Ipv_End as ipvEnd,
        ims.Ims_Planned_Inv,
        ims.ims_cumulative_inv,
        ims.ims_cumulative_inv_proportion,
        
            IFNULL(jbrAgg.all_names, u.u_name) as cjJbr,
        
        depAgg.dep_names as pCompetentDepartmentNames,
        mn.*
        from Inv_Complete_Month mn
        left join Con_Contract con on con.Con_Id = mn.Con_Id
        Left join Inv_Plan_Year ipv ON mn.p_id = ipv.p_id and mn.icm_reporting_year = ipv.Ipv_Declare_Year and Ipv_State != 1 and ipv_state != 3
        LEFT join Inv_Monthly_Schedule ims ON ims.Ipv_Id = ipv.Ipv_Id and ims.Ims_Month = mn.Icm_Reporting_Month
        
        
            
        
        
            
        
        
        left join SYS_Department sdp on pro.p_Department=sdp.D_ID
        left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID
        
            ${params.authSql}
        
        
            WHERE 1=1
        

        
            and mn.Te_Id = #{params.teId}
        
        
            and mn.Icm_Create_Uid = #{params.createdBy}
        
        
            and mn.Icm_D_Id = #{params.icmDId}
        
        
            and mn.P_Id = #{params.pId}
        
        
            and mn.Icm_Reporting_Year = #{params.icmReportingYear}
        
        
            and mn.Icm_Reporting_Month = #{params.icmReportingMonth}
        
        
            and mn.Icm_State = #{params.icmState}
        
        
            
                
                    and likePname(#{params.pName},pro.P_Id)=true
                
                
                    and pro.P_Name like concat('%',#{params.pName},'%')
                
            
        
        
            and pro.P_Competent_Department = #{params.pCompetentDepartment}
        
        
            and mn.transfer_status in
            
                #{item}
            
        
        
            and ipv.Ipv_P_Type in
            
                #{item}
            
        
        
            and mn.plan_complete_result IN
            
                #{item}
            
        
        
            and mn.complete_result IN
            
                #{item}
            
        
        
            and mn.month_cumulative_inv_proportion < #{params.monthCumulativeInvProportion}
        
        
            and ipv.ipv_p_type in
            
                #{type}
            
        
        
            and ipv.Ipv_Construction_stage in
            
                #{stage}
            
        
        
            and
            
                INSTR(ipv.Ipv_Construction_stage, #{ipvStaqe})
            
        
        
            and pro.p_name  in
            
                #{pName}
            
        
        
            and (sdp.D_Name in
            
                #{pDepartmentName}
            
            
                or (sdp.D_Name is null or sdp.D_Name = '')
            
            )
        
        
            and (depAgg.dep_names in
            
                #{pCompetentDepartmentName}
            
            
                or (depAgg.dep_names is null or depAgg.dep_names = '')
            
            )
        
        
            and mn.icm_Create_Uname  in
            
                #{createUname}
            
        
        
            and ( pro.p_Competent_Department in
            
                #{dep}
            
            or
            pro.P_Department in
            
                #{dep}
            
            )
        
        
            and ((
            jbrHit.p_id is not null
            or exists (
            select 1
            from sys_user engineer
            where engineer.u_id = pro.P_Engineer
            and engineer.u_name in
            
                #{jbr}
            
            ))
            
                or (
                jbrAgg.p_id is null
                and pro.P_Engineer is null
                )
            
            )
        
        
            and (ipv.ipv_construction_status in
            
                #{status}
            
            
                or (ipv.ipv_construction_status is null or ipv.ipv_construction_status = '')
            
            )
        
        
            
        
        
            
                order by mn.${params.sortFiled} ${params.sortType}
            
            
                
                    order by CAST(ipv.report_table_num AS UNSIGNED) ${params.sortType}
                
                
                    order by ${params.sortSideFiled} ${params.sortType}
                
            
            
                order by mn.Icm_Create_Time desc

SELECT ipv.P_ID, pp.P_Competent_Department, sd.D_Name as pCompetentDepartmentName FROM Inv_Plan_Year ipv LEFT join Pre_Project pp ON pp.P_ID = ipv.P_ID and pp.P_Competent_Department is not null LEFT join SYS_Department sd on pp.P_Competent_Department=sd.D_Id WHERE ipv.Ipv_Declare_Year = #{icmReportingYear} and ipv.P_ID is not null and sd.D_Id is not null
and ipv.Ipv_P_Type in
#{item}
and pp.P_Competent_Department in
#{item}

select *
from Inv_Complete_Month mn
where mn.p_Id = #{pId} and mn.Icm_Reporting_Month = #{gfpMonth} and mn.Icm_Reporting_Year = #{gfpYear}

select * from Inv_Complete_Month icm

    icm.Icm_State=7
    
        and icm.p_Id = #{projectId}
    
    
        and icm.Icm_Reporting_Year = #{year}

select

sd.D_Name as icmDName,
mn.Ipv_P_Type,
mn.report_table_num + 0 as reportTableNum,
ims.Ims_Planned_Inv,
ims.ims_cumulative_inv,
ims.ims_cumulative_inv_proportion,
icm.*
from Inv_Complete_Month icm
Left join Inv_Plan_Year mn ON icm.p_id = mn.p_id and icm.icm_reporting_year = mn.Ipv_Declare_Year and mn.Ipv_State != 1 and mn.ipv_state != 3 and mn.Ipv_Id = icm.Ipv_Id
LEFT join Inv_Monthly_Schedule ims ON ims.Ipv_Id = mn.Ipv_Id and ims.Ims_Month = icm.Icm_Reporting_Month

left join SYS_Department sd on icm.Icm_D_Id=sd.D_ID
${authSql}

    and mn.report_table_num in
    
        #{item}
    


    and pro.P_Name in
    
        #{item}
    


    and prod.D_Name in
    
        #{item}
    


    and mn.ipv_p_type in
    
        #{item}
    


    and icm.icm_reporting_year in
    
        #{item}
    


    and icm.icm_reporting_month in
    
        #{item}
    


    and icm.current_month_start in
    
        #{item}
    


    and icm.cumulative_start in
    
        #{item}
    


    and icm.plan_complete_result in
    
        #{item}
    


    and icm.current_month_complete in
    
        #{item}
    


    and icm.cumulative_complete in
    
        #{item}
    


    and icm.complete_result in
    
        #{item}
    


    and to_char(icm.plan_start_time,'yyyy-MM') = #{request.planStartTime}


    and to_char(icm.plan_end_time,'yyyy-MM') = #{request.planEndTime}


    and to_char(icm.actual_start_time,'yyyy-MM') = #{request.actualStartTime}


    and to_char(icm.actual_end_time,'yyyy-MM') = #{request.actualEndTime}


    and icm.icm_monthly_investment in
    
        #{item}
    


    and icm.icm_annual_investment in
    
        #{item}
    


    and icm.icm_annual_proportion in
    
        #{item}
    


