mapper.sql:
left join (
select distinct dp.p_id as p_id
from sys_user up
join SYS_Position_User_P pup on pup.u_id = up.u_id
join SYS_Position_P pp       on pp.pp_id = pup.pp_id
join SYS_Department_P dp     on dp.pd_id = pp.pd_id
where pp.PP_Code = #{params.jbr}
and up.u_name in

    #{jbr}

) jbrHit on jbrHit.p_id = mn.P_Id

mapper.select:
select

sdp.d_name as pDepartmentName,
con.Con_Name as conName,
ipv.Ipv_P_Type,
ipv.ipv_Construction_Stage as ipvConstructionStage,
ipv.ipv_construction_status as ipvConstructionStatus,
ipv.report_table_num + 0 as reportTableNum,
ipv.Ipv_Planned_Investment as ipvPlannedInvestment,
ipv.Ipv_Start as ipvStart,
ipv.Ipv_End as ipvEnd,
ims.Ims_Planned_Inv,
ims.ims_cumulative_inv,
ims.ims_cumulative_inv_proportion,
depAgg.dep_names as pCompetentDepartmentNames,
mn.*
from Inv_Complete_Month mn
left join Con_Contract con on con.Con_Id = mn.Con_Id
Left join Inv_Plan_Year ipv ON mn.p_id = ipv.p_id and mn.icm_reporting_year = ipv.Ipv_Declare_Year and Ipv_State != 1 and ipv_state != 3
LEFT join Inv_Monthly_Schedule ims ON ims.Ipv_Id = ipv.Ipv_Id and ims.Ims_Month = mn.Icm_Reporting_Month


left join SYS_Department sdp on pro.p_Department=sdp.D_ID
left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID

    
        
    
    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Icm_Create_Uid = #{params.createdBy}
    
    
        and mn.Icm_D_Id = #{params.icmDId}
    
    
        and mn.P_Id = #{params.pId}
    
    
        and mn.Icm_Reporting_Year = #{params.icmReportingYear}
    
    
        and mn.Icm_Reporting_Month = #{params.icmReportingMonth}
    
    
        and mn.Icm_State = #{params.icmState}
    
    
        
            
                and likePname(#{params.pName},pro.P_Id)=true
            
            
                and pro.P_Name like concat('%',#{params.pName},'%')
            
        
    
    
        and pro.P_Competent_Department = #{params.pCompetentDepartment}
    
    
        and mn.transfer_status in
        
            #{item}
        
    
    
        and ipv.Ipv_P_Type in
        
            #{item}
        
    
    
        and mn.plan_complete_result IN
        
            #{item}
        
    
    
        and mn.complete_result IN
        
            #{item}
        
    
    
        and mn.month_cumulative_inv_proportion < #{params.monthCumulativeInvProportion}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        
            order by CAST(ipv.report_table_num AS UNSIGNED) ${params.sortType}
        
        
            order by ${params.sortSideFiled} ${params.sortType}
        
    
    
        order by mn.Icm_Create_Time desc
